('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Mängelanzeige erstelle?', 3, '[{"text": "Auswirkungen", "correct": false, "because": "Zeigt Dringlichkeit"}, {"text": "Fehlerursache", "correct": false, "because": "Hilft bei Lösung"}, {"text": "Dekoratives Layout", "correct": true, "because": "Kein Mängelfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Mängelanzeige nur für Kunden relevant?', 3, '[{"text": "Nein", "correct": true, "because": "Auch intern nützlich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
